create table if not exists public.shipping_provider_catalog (
  provider_code text primary key,
  provider_name text not null,
  provider_type text not null check (provider_type in ('multi_carrier','direct_carrier')),
  connection_method text not null check (connection_method in ('api_credentials','oauth','account_credentials','manual')),
  website_url text, documentation_url text, setup_url text, description text, setup_instructions text,
  required_fields jsonb not null default '[]'::jsonb, capabilities jsonb not null default '{}'::jsonb,
  availability text not null default 'available' check (availability in ('available','setup_required','planned')),
  adapter_status text not null default 'planned' check (adapter_status in ('active','framework_ready','planned')),
  sort_order integer not null default 100, enabled boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);

alter table public.shipping_provider_connections add column if not exists credentials_vault_id uuid;
alter table public.shipping_provider_connections drop constraint if exists shipping_provider_connections_provider_check;
alter table public.shipping_provider_connections add constraint shipping_provider_connections_provider_check
check (provider = any (array['parcel2go','sendcloud','shippo','shiptheory','scurri','metapack','linnworks','royalmail','evri','yodel','dpd','dhl','parcelforce','ups','fedex','dx','apc','inpost','whistl','amazon_shipping']));

alter table public.shipping_provider_catalog enable row level security;
drop policy if exists shipping_provider_catalog_public_select on public.shipping_provider_catalog;
create policy shipping_provider_catalog_public_select on public.shipping_provider_catalog for select to authenticated using (enabled=true);
grant select on public.shipping_provider_catalog to authenticated;

