on conflict (provider_code) do update set provider_name=excluded.provider_name,provider_type=excluded.provider_type,connection_method=excluded.connection_method,website_url=excluded.website_url,documentation_url=excluded.documentation_url,setup_url=excluded.setup_url,description=excluded.description,setup_instructions=excluded.setup_instructions,required_fields=excluded.required_fields,capabilities=excluded.capabilities,availability=excluded.availability,adapter_status=excluded.adapter_status,sort_order=excluded.sort_order,updated_at=now();

create or replace function public.subscriber_save_shipping_provider_connection(p_tenant_id uuid,p_provider text,p_environment text,p_credentials jsonb,p_config jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path=public,private,vault as $function$
declare v_catalog public.shipping_provider_catalog%rowtype; v_secret_id uuid; v_connection_id uuid;
begin
 if auth.uid() is null or not private.has_tenant_permission(p_tenant_id,auth.uid(),'tenant.manage') then raise exception 'Not authorised'; end if;
 select * into v_catalog from public.shipping_provider_catalog where provider_code=p_provider and enabled=true;
 if not found then raise exception 'Shipping provider is not available'; end if;
 if p_environment not in ('sandbox','live') then raise exception 'Invalid environment'; end if;
 if coalesce(jsonb_typeof(p_credentials),'object')<>'object' or p_credentials='{}'::jsonb then raise exception 'Enter the required connection details'; end if;
 v_secret_id:=vault.create_secret(p_credentials::text,'tradeflow_shipping_credentials_'||p_tenant_id::text||'_'||p_provider,'TradeFlow shipping provider credentials');
 insert into public.shipping_provider_connections(tenant_id,provider,status,connection_type,environment,auth_mode,credentials_vault_id,metadata,updated_at)
 values(p_tenant_id,p_provider,'pending','subscriber_account',p_environment,v_catalog.connection_method,v_secret_id,coalesce(p_config,'{}'::jsonb),now())
 on conflict (tenant_id,provider) do update set status='pending',environment=excluded.environment,auth_mode=excluded.auth_mode,credentials_vault_id=excluded.credentials_vault_id,metadata=excluded.metadata,disconnected_at=null,updated_at=now()
 returning id into v_connection_id;
 return jsonb_build_object('ok',true,'connection_id',v_connection_id,'status','pending','adapter_status',v_catalog.adapter_status);
end;$function$;

create or replace function public.shipping_provider_credentials_for_service(p_connection_id uuid)
returns jsonb language plpgsql security definer set search_path=public,private,vault as $function$
declare v_secret text;
begin
 if current_user<>'service_role' then raise exception 'Not authorised'; end if;
 select ds.decrypted_secret into v_secret from vault.decrypted_secrets ds join public.shipping_provider_connections c on c.credentials_vault_id=ds.id where c.id=p_connection_id;
 if v_secret is null then raise exception 'Provider credentials not found'; end if;
 return v_secret::jsonb;
end;$function$;

revoke execute on function public.subscriber_save_shipping_provider_connection(uuid,text,text,jsonb,jsonb) from anon;
grant execute on function public.subscriber_save_shipping_provider_connection(uuid,text,text,jsonb,jsonb) to authenticated;
revoke execute on function public.shipping_provider_credentials_for_service(uuid) from public,anon,authenticated;
grant execute on function public.shipping_provider_credentials_for_service(uuid) to service_role;
